// frontend/src/components/Search.js

import React, { useState, useContext } from "react";
import axios from "../utils/axiosInstance";
import GeneralContext from "./GeneralContext";

const Search = () => {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);
  const { refreshWatchlist } = useContext(GeneralContext);

  const handleSearch = async (e) => {
    const val = e.target.value;
    setQuery(val);
    if (val.length < 2) return setResults([]);

    const exchanges = [".NS", ".BO"]; // NSE, BSE
    const formatted = exchanges.map((ex) => `${val.toUpperCase()}${ex}`);

    const searchResults = [];
    for (let symbol of formatted) {
      try {
        const res = await axios.get(`/price/${symbol}`);
        searchResults.push({
          symbol,
          name: symbol, // You can use a lookup API later for full name
          price: res.data.price,
          exchange: symbol.endsWith(".NS") ? "NSE" : "BSE",
        });
      } catch (err) {
        // Ignore failed lookups
      }
    }

    setResults(searchResults);
  };

  const addToWatchlist = async (symbol) => {
    try {
      await axios.post("/api/watchlist", { symbol }); // your existing endpoint
      refreshWatchlist();
      setQuery("");
      setResults([]);
    } catch (err) {
      console.error("Add failed:", err);
    }
  };

  return (
    <div className="search-container">
      <input
        type="text"
        value={query}
        onChange={handleSearch}
        placeholder="Search e.g. INFY, SBIN, RELIANCE"
        className="search"
      />
      {results.length > 0 && (
        <ul className="search-results">
          {results.map((stock, idx) => (
            <li key={idx} onClick={() => addToWatchlist(stock.symbol)}>
              {stock.name} ({stock.symbol}) - ₹{stock.price} - {stock.exchange}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Search;
